export function imageDimensions(src: string) {
  const key = src.split("?")[0];
  const variants = responsiveImages[key];
  return { ...dimensions[key], ...(variants ? { srcSet: variants.map(image => `${image.src} ${image.width}w`).join(", "), sizes: "(max-width: 700px) 100vw, 50vw" } : {}) };
}

/** Efficient posters and decoded swaps; full-resolution originals remain available. */
export function optimizedSource(src: string) {
  return responsiveImages[src.split("?")[0]]?.at(-1)?.src ?? src;
}
